yaml_template:
# Speaker Tuner {{tool_version}}: {{profile_name}}
# Device: {{device_name}}, exported {{date}}
#
# 1. Add these substitutions to your device YAML (merge with an existing substitutions: block).
# 2. Replace the crossover: block under audio_dac: - platform: tas58xx with the one below.
#    Keep your other audio_dac options (id, enable_pin, analog_gain, mixer_mode, ...).
# 3. Flash, then press "Reset Crossover to YAML" so these values replace the ones saved
#    on the device. Values set from Home Assistant are saved anyway; this makes them
#    the YAML defaults so they survive a factory reset and can be copied to another cabinet.

substitutions:
  xo_filter: "{{crossover_filter_code}}"
  xo_frequency: "{{crossover_frequency}}Hz"
  xo_tweeter_min_frequency: "{{tweeter_min_frequency}}Hz"
  xo_tweeter_gain: "{{tweeter_gain}}dB"
  xo_mid_gain: "{{mid_gain}}dB"
  xo_tweeter_invert: "{{tweeter_invert}}"
  xo_mid_invert: "{{mid_invert}}"
  xo_tweeter_delay: "{{tweeter_delay}}"
  xo_mid_delay: "{{mid_delay}}"
  xo_subsonic_frequency: "{{subsonic_frequency}}Hz"
  xo_baffle_width: "{{baffle_width}}"
  xo_baffle_placement: "{{baffle_placement_code}}"
  xo_notch_frequency: "{{tweeter_notch_frequency}}Hz"
  xo_notch_gain: "{{tweeter_notch_gain}}dB"
  xo_notch_q: "{{tweeter_notch_q}}"
  xo_air_gain: "{{air_gain}}dB"
  xo_linkwitz_f0: "{{linkwitz_f0}}Hz"
  xo_linkwitz_q0: "{{linkwitz_q0}}"
  xo_linkwitz_fp: "{{linkwitz_fp}}Hz"
  xo_linkwitz_qp: "{{linkwitz_qp}}"
  xo_headroom_compensation: "{{headroom_compensation}}"
  xo_loudness: "{{loudness}}"
  xo_loudness_reference: "{{loudness_reference}}dB"
  tweeter_peq_1_frequency: "{{tweeter_peq_1_frequency}}Hz"
  tweeter_peq_1_gain: "{{tweeter_peq_1_gain}}dB"
  tweeter_peq_1_q: "{{tweeter_peq_1_q}}"
  tweeter_peq_1_type: "{{tweeter_peq_1_type_code}}"
  tweeter_peq_2_frequency: "{{tweeter_peq_2_frequency}}Hz"
  tweeter_peq_2_gain: "{{tweeter_peq_2_gain}}dB"
  tweeter_peq_2_q: "{{tweeter_peq_2_q}}"
  tweeter_peq_2_type: "{{tweeter_peq_2_type_code}}"
  tweeter_peq_3_frequency: "{{tweeter_peq_3_frequency}}Hz"
  tweeter_peq_3_gain: "{{tweeter_peq_3_gain}}dB"
  tweeter_peq_3_q: "{{tweeter_peq_3_q}}"
  tweeter_peq_3_type: "{{tweeter_peq_3_type_code}}"
  tweeter_peq_4_frequency: "{{tweeter_peq_4_frequency}}Hz"
  tweeter_peq_4_gain: "{{tweeter_peq_4_gain}}dB"
  tweeter_peq_4_q: "{{tweeter_peq_4_q}}"
  tweeter_peq_4_type: "{{tweeter_peq_4_type_code}}"
  tweeter_peq_5_frequency: "{{tweeter_peq_5_frequency}}Hz"
  tweeter_peq_5_gain: "{{tweeter_peq_5_gain}}dB"
  tweeter_peq_5_q: "{{tweeter_peq_5_q}}"
  tweeter_peq_5_type: "{{tweeter_peq_5_type_code}}"
  tweeter_peq_6_frequency: "{{tweeter_peq_6_frequency}}Hz"
  tweeter_peq_6_gain: "{{tweeter_peq_6_gain}}dB"
  tweeter_peq_6_q: "{{tweeter_peq_6_q}}"
  tweeter_peq_6_type: "{{tweeter_peq_6_type_code}}"
  mid_peq_1_frequency: "{{mid_peq_1_frequency}}Hz"
  mid_peq_1_gain: "{{mid_peq_1_gain}}dB"
  mid_peq_1_q: "{{mid_peq_1_q}}"
  mid_peq_1_type: "{{mid_peq_1_type_code}}"
  mid_peq_2_frequency: "{{mid_peq_2_frequency}}Hz"
  mid_peq_2_gain: "{{mid_peq_2_gain}}dB"
  mid_peq_2_q: "{{mid_peq_2_q}}"
  mid_peq_2_type: "{{mid_peq_2_type_code}}"
  mid_peq_3_frequency: "{{mid_peq_3_frequency}}Hz"
  mid_peq_3_gain: "{{mid_peq_3_gain}}dB"
  mid_peq_3_q: "{{mid_peq_3_q}}"
  mid_peq_3_type: "{{mid_peq_3_type_code}}"
  mid_peq_4_frequency: "{{mid_peq_4_frequency}}Hz"
  mid_peq_4_gain: "{{mid_peq_4_gain}}dB"
  mid_peq_4_q: "{{mid_peq_4_q}}"
  mid_peq_4_type: "{{mid_peq_4_type_code}}"
  mid_peq_5_frequency: "{{mid_peq_5_frequency}}Hz"
  mid_peq_5_gain: "{{mid_peq_5_gain}}dB"
  mid_peq_5_q: "{{mid_peq_5_q}}"
  mid_peq_5_type: "{{mid_peq_5_type_code}}"
  mid_peq_6_frequency: "{{mid_peq_6_frequency}}Hz"
  mid_peq_6_gain: "{{mid_peq_6_gain}}dB"
  mid_peq_6_q: "{{mid_peq_6_q}}"
  mid_peq_6_type: "{{mid_peq_6_type_code}}"

# under audio_dac: - platform: tas58xx
    crossover:
      filter: ${xo_filter}
      frequency: ${xo_frequency}
      tweeter_min_frequency: ${xo_tweeter_min_frequency}
      tweeter_channel: {{crossover_tweeter_channel_code}}
      tweeter_gain: ${xo_tweeter_gain}
      mid_gain: ${xo_mid_gain}
      tweeter_invert: ${xo_tweeter_invert}
      mid_invert: ${xo_mid_invert}
      tweeter_delay: ${xo_tweeter_delay}
      mid_delay: ${xo_mid_delay}
      tweeter_peq:
        - frequency: ${tweeter_peq_1_frequency}
          gain: ${tweeter_peq_1_gain}
          q: ${tweeter_peq_1_q}
          type: ${tweeter_peq_1_type}
        - frequency: ${tweeter_peq_2_frequency}
          gain: ${tweeter_peq_2_gain}
          q: ${tweeter_peq_2_q}
          type: ${tweeter_peq_2_type}
        - frequency: ${tweeter_peq_3_frequency}
          gain: ${tweeter_peq_3_gain}
          q: ${tweeter_peq_3_q}
          type: ${tweeter_peq_3_type}
        - frequency: ${tweeter_peq_4_frequency}
          gain: ${tweeter_peq_4_gain}
          q: ${tweeter_peq_4_q}
          type: ${tweeter_peq_4_type}
        - frequency: ${tweeter_peq_5_frequency}
          gain: ${tweeter_peq_5_gain}
          q: ${tweeter_peq_5_q}
          type: ${tweeter_peq_5_type}
        - frequency: ${tweeter_peq_6_frequency}
          gain: ${tweeter_peq_6_gain}
          q: ${tweeter_peq_6_q}
          type: ${tweeter_peq_6_type}
      mid_peq:
        - frequency: ${mid_peq_1_frequency}
          gain: ${mid_peq_1_gain}
          q: ${mid_peq_1_q}
          type: ${mid_peq_1_type}
        - frequency: ${mid_peq_2_frequency}
          gain: ${mid_peq_2_gain}
          q: ${mid_peq_2_q}
          type: ${mid_peq_2_type}
        - frequency: ${mid_peq_3_frequency}
          gain: ${mid_peq_3_gain}
          q: ${mid_peq_3_q}
          type: ${mid_peq_3_type}
        - frequency: ${mid_peq_4_frequency}
          gain: ${mid_peq_4_gain}
          q: ${mid_peq_4_q}
          type: ${mid_peq_4_type}
        - frequency: ${mid_peq_5_frequency}
          gain: ${mid_peq_5_gain}
          q: ${mid_peq_5_q}
          type: ${mid_peq_5_type}
        - frequency: ${mid_peq_6_frequency}
          gain: ${mid_peq_6_gain}
          q: ${mid_peq_6_q}
          type: ${mid_peq_6_type}
      subsonic_frequency: ${xo_subsonic_frequency}
      baffle_width: ${xo_baffle_width}
      baffle_placement: ${xo_baffle_placement}
      tweeter_notch:
        frequency: ${xo_notch_frequency}
        gain: ${xo_notch_gain}
        q: ${xo_notch_q}
      air_gain: ${xo_air_gain}
      linkwitz:
        f0: ${xo_linkwitz_f0}
        q0: ${xo_linkwitz_q0}
        fp: ${xo_linkwitz_fp}
        qp: ${xo_linkwitz_qp}
      headroom_compensation: ${xo_headroom_compensation}
      loudness: ${xo_loudness}
      loudness_reference: ${xo_loudness_reference}
      dsp_sample_rate: {{dsp_sample_rate}}Hz
